const round4 = (n: number): number => Math.round(n * 10000) / 10000;

export function attributionAccuracy(
  pred: { id: string; predicted: string }[],
  key: { id: string; actual: string }[],
): { correct: number; total: number; accuracy: number; missing: string[] } {
  const predicted = new Map(pred.map((p) => [p.id, p.predicted]));
  let correct = 0;
  const missing: string[] = [];
  for (const k of key) {
    const p = predicted.get(k.id);
    if (p === undefined) missing.push(k.id);
    else if (p === k.actual) correct++;
  }
  const total = key.length;
  return { correct, total, accuracy: total === 0 ? 0 : round4(correct / total), missing };
}

export function tagAccuracy(
  rows: { inferredSetup: string | null; tag: string | null }[],
): { correct: number; total: number; accuracy: number } {
  const tagged = rows.filter((r) => r.tag !== null);
  const counts = new Map<string, Map<string, number>>();
  for (const r of tagged) {
    if (r.inferredSetup === null) continue;
    const m = counts.get(r.inferredSetup) ?? new Map<string, number>();
    m.set(r.tag as string, (m.get(r.tag as string) ?? 0) + 1);
    counts.set(r.inferredSetup, m);
  }
  // Majority vote per inferred cluster; ties break on the lexicographically smallest tag.
  const mapping = new Map<string, string>();
  for (const [cluster, m] of counts) {
    let best: string | null = null;
    let bestN = 0;
    for (const [tag, n] of m) {
      if (n > bestN || (n === bestN && best !== null && tag < best)) {
        best = tag;
        bestN = n;
      }
    }
    if (best !== null) mapping.set(cluster, best);
  }
  let correct = 0;
  for (const r of tagged) {
    if (r.inferredSetup !== null && mapping.get(r.inferredSetup) === r.tag) correct++;
  }
  const total = tagged.length;
  return { correct, total, accuracy: total === 0 ? 0 : round4(correct / total) };
}
