import { describe, expect, test } from "bun:test";
import { attributionAccuracy, tagAccuracy } from "../src/attribution/evaluate";

describe("attributionAccuracy", () => {
  test("counts correct, wrong and missing", () => {
    const r = attributionAccuracy(
      [{ id: "a", predicted: "x" }, { id: "b", predicted: "y" }],
      [{ id: "a", actual: "x" }, { id: "b", actual: "z" }, { id: "c", actual: "x" }],
    );
    expect(r).toEqual({ correct: 1, total: 3, accuracy: 0.3333, missing: ["c"] });
  });
  test("empty key gives 0", () => {
    expect(attributionAccuracy([], [])).toEqual({ correct: 0, total: 0, accuracy: 0, missing: [] });
  });
});

describe("tagAccuracy", () => {
  test("majority vote maps clusters to tags; untagged rows ignored", () => {
    const r = tagAccuracy([
      { inferredSetup: "c1", tag: "A" },
      { inferredSetup: "c1", tag: "A" },
      { inferredSetup: "c1", tag: "B" },
      { inferredSetup: "c2", tag: "B" },
      { inferredSetup: "c2", tag: null },
      { inferredSetup: null, tag: null },
    ]);
    expect(r).toEqual({ correct: 3, total: 4, accuracy: 0.75 });
  });
  test("tagged row with null inference is wrong; no tags gives 0", () => {
    expect(tagAccuracy([{ inferredSetup: null, tag: "A" }])).toEqual({ correct: 0, total: 1, accuracy: 0 });
    expect(tagAccuracy([{ inferredSetup: "c", tag: null }])).toEqual({ correct: 0, total: 0, accuracy: 0 });
  });
});
